package dk.sdu.cbse.gamelab; import java.util.*; public final class AsteroidComponent implements IGamePluginService,IEntityProcessingService{public void start(GameData d){Random r=new Random(5);for(int i=0;i<6;i++){Entity a=new Entity("ASTEROID",r.nextInt(800),r.nextInt(600),20+r.nextInt(15));a.dx=-35+r.nextDouble()*70;a.dy=-35+r.nextDouble()*70;d.entities.add(a);}}public void stop(GameData d){d.entities.removeIf(e->e.type.equals("ASTEROID"));}public void process(GameData d,double dt){for(Entity a:d.entities.stream().filter(e->e.type.equals("ASTEROID")).toList()){a.x+=a.dx*dt;a.y+=a.dy*dt;d.wrap(a);}}}